# protein GPT-2 medium -- batch 1024, lr 3.79e-04  (grid)
# The protein batch-size grid of the 2026-11-20 directive. Generated by
# scripts/protein_batch_sweep_configs.py from the derived arm inventory; edit the
# inventory and regenerate rather than editing this file.
#
# Budget fixed in columns, not steps (section 2): 85,708,800 packed blocks of 1024
# tokens = 87,765,811,200 tokens, the same for every arm. At batch 1024 that is 83,700
# iterations, so the five batches cover the same data and compare at the same column.
#
# Rate = this size's 2,560 rate x sqrt(batch/2560) x 1.0 (section 3).
# Warmup 2 % of this arm's length, truncated: 1,674 of 83,700 (section 2).
#
# One GPU takes 64 columns (MEASURED, section 4) and accumulation carries the rest:
# 64 x 16 = 1024.

from molcrawl.core.paths import UNIPROT_DATASET_DIR, get_gpt2_output_path
from molcrawl.data.protein_sequence.dataset.tokenizer import EsmSequenceTokenizer as Tokenizer

dataset_dir = UNIPROT_DATASET_DIR
tensorboard_dir = get_gpt2_output_path("protein_sequence", "medium") + "-b1024-lr3p79e4"
out_dir = get_gpt2_output_path("protein_sequence", "medium") + "-b1024-lr3p79e4"

tokenizer = Tokenizer()
meta_vocab_size = tokenizer.vocab_size

# nanoGPT divides gradient_accumulation_steps by world size, so effective batch =
# batch_size x gradient_accumulation_steps (GPU-count-independent). 64 x 16 = 1024.
batch_size = 64
block_size = 1024
gradient_accumulation_steps = 16
expected_global_batch = 1024  # train.py refuses to start if micro x accum disagrees (section 5)

max_iters = 83700
lr_decay_iters = 83700  # = max_iters (section 8)
min_lr = 3.79e-05          # peak/10 (section 8)
warmup_iters = 1674            # 2 % of max_iters (section 2)
learning_rate = 0.000379
dtype = "bfloat16"

eval_interval = 372
log_interval = 46
eval_sequences = 3200  # fix the val *sequence* count, GPU-count-independent

# "resume", not "scratch": an arm runs as an afterany chain of segments (the budget
# outruns the limit at xl, and leaves the others close), and nanoGPT's resume starts
# fresh when out_dir is empty (link 1) and continues from the latest checkpoint after
# (link N). pretrain_dir is left unset, so an empty dir means scratch, not an error.
init_from = "resume"
always_save_checkpoint = False
save_checkpoint_steps = 1860
max_checkpoints = 10
early_stopping = False  # run the whole schedule (section 8)

weight_decay = 0.1
dropout = 0.0

dataset = "protein_sequence"
dataset_params = {"dataset_dir": dataset_dir}

# EsmSequenceTokenizer: <cls>=0, <pad>=1, <eos>=2
bos_token_id = 0
eos_token_id = 2
pad_token_id = 1

seed = 42
